from typing import List


class ParseError(ValueError):
    pass


def parse_line(line: str, delimiter: str = ",", quote: str = '"') -> List[str]:
    if len(delimiter) != 1:
        raise ParseError("delimiter must be one character")
    if len(quote) != 1:
        raise ParseError("quote must be one character")
    if delimiter == quote:
        raise ParseError("delimiter and quote must differ")
    if line == "":
        return []
    fields = []
    i, n = 0, len(line)
    while True:
        if i < n and line[i] == quote:
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ParseError("unterminated quoted field")
                ch = line[i]
                if ch == quote:
                    if i + 1 < n and line[i + 1] == quote:
                        buf.append(quote)
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(ch)
                i += 1
            if i < n and line[i] != delimiter:
                raise ParseError("unexpected character after closing quote")
            fields.append("".join(buf))
        else:
            start = i
            while i < n and line[i] != delimiter:
                if line[i] == quote:
                    raise ParseError("quote inside unquoted field")
                i += 1
            fields.append(line[start:i])
        if i >= n:
            return fields
        i += 1  # skip delimiter; a trailing one yields a final empty field
